-- ================================================================
-- Korea Trekking Hub — 지자체 운영 공공 캠핑장 329건 적재
-- 파일: camps_seed.sql (csv_data/공공캠핑장/)
--
-- Node 없이 Supabase SQL Editor 에 그대로 붙여넣어 실행하는 용도입니다.
-- 008_create_camps_schema.sql 을 먼저 실행해 두세요.
--
-- 여러 번 실행해도 안전합니다:
--   · 마스터 정보(이름·좌표·운영기관 등)는 이 파일 값으로 갱신
--   · 예약 정보는 이 파일이 빈 값이면 DB의 기존 값을 유지 (지도에서 입력한 내용 보존)
--
-- 좌표가 없는 35건(고캠핑 보강분)은 geocoded = FALSE 로 들어가 지도에 표시되지 않습니다.
-- Node 가 있는 환경에서 `npx tsx scripts/seed_camps.ts` 를 돌리면 카카오 API 로 채워집니다.
-- ================================================================

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  category = EXCLUDED.category,
  type_detail = EXCLUDED.type_detail,
  region = EXCLUDED.region,
  sido = EXCLUDED.sido,
  sigungu = EXCLUDED.sigungu,
  address = EXCLUDED.address,
  lat = EXCLUDED.lat,
  lng = EXCLUDED.lng,
  geocoded = EXCLUDED.geocoded,
  operator = EXCLUDED.operator,
  operator_level = EXCLUDED.operator_level,
  operator_verified = EXCLUDED.operator_verified,
  tel = EXCLUDED.tel,
  facilities = EXCLUDED.facilities,
  source = EXCLUDED.source,
  reservation_org = COALESCE(NULLIF(EXCLUDED.reservation_org, ''), public.camps.reservation_org),
  reservation_url = COALESCE(NULLIF(EXCLUDED.reservation_url, ''), public.camps.reservation_url),
  reservation_open = COALESCE(NULLIF(EXCLUDED.reservation_open, ''), public.camps.reservation_open),
  use_season = COALESCE(NULLIF(EXCLUDED.use_season, ''), public.camps.use_season),
  reservation_note = COALESCE(NULLIF(EXCLUDED.reservation_note, ''), public.camps.reservation_note);

